package lk.ac.sliit.ridelink.driver.infrastructure.persistence.mapper;
import lk.ac.sliit.ridelink.driver.domain.model.Vehicle; import lk.ac.sliit.ridelink.driver.infrastructure.persistence.entity.VehicleJpaEntity;
public final class VehiclePersistenceMapper { private VehiclePersistenceMapper(){} public static VehicleJpaEntity entity(Vehicle v){return new VehicleJpaEntity(v.getId(),v.getDriverId(),v.getRegistrationNumber(),v.getMake(),v.getModel(),v.getColour(),v.getVehicleType(),v.getManufacturingYear(),v.isActive(),v.getCreatedAt(),v.getUpdatedAt());} public static Vehicle domain(VehicleJpaEntity e){return new Vehicle(e.getId(),e.getDriverId(),e.getRegistrationNumber(),e.getMake(),e.getModel(),e.getColour(),e.getVehicleType(),e.getManufacturingYear(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());} }
